import { Component, OnInit, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { NavigationComponent } from '../../core/components/navigation.component';
import { FooterComponent } from '../../core/components/footer.component';

@Component({
    selector: 'app-service-categories',
    standalone: true,
    imports: [CommonModule, NavigationComponent, FooterComponent],
    template: `
        <app-navigation></app-navigation>
        <main class="pt-20 pb-10">
            <!-- Sticky Header -->
            <div [ngClass]="{'fixed top-16 left-0 right-0 bg-white shadow-lg z-40': isSticky}"
                 class="transition-all duration-300">
                <div class="max-w-7xl mx-auto px-6 py-4 flex gap-4 overflow-x-auto">
                    <button *ngFor="let cat of categories"
                            (click)="scrollToCategory(cat.id)"
                            [ngClass]="{'bg-soft-gold text-charcoal': activeCategory === cat.id, 'text-charcoal': activeCategory !== cat.id}"
                            class="px-4 py-2 font-semibold whitespace-nowrap rounded-full transition-all">
                        {{ cat.icon }} {{ cat.name }}
                    </button>
                </div>
            </div>

            <div [ngClass]="{'mt-24': isSticky}" class="transition-all duration-300">
                <div *ngFor="let category of categories" [id]="category.id"
                     class="py-12 px-6 border-b border-gray-200">
                    <div class="max-w-7xl mx-auto">
                        <h2 class="text-4xl font-bold mb-8 text-charcoal">
                            {{ category.icon }} {{ category.name }}
                        </h2>
                        <div *ngFor="let sub of category.subCategories" class="mb-8">
                            <h3 class="text-2xl font-semibold mb-4 text-misty-blue">{{ sub.name }}</h3>
                            <div class="grid md:grid-cols-2 gap-4">
                                <div *ngFor="let item of sub.items"
                                     class="bg-white p-4 rounded-lg shadow hover:shadow-lg transition-shadow">
                                    {{ item }}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </main>
        <app-footer></app-footer>
    `
})
export class ServiceCategoriesComponent implements OnInit {
    isSticky = false;
    activeCategory = 'hair';
    isProgrammaticScroll = false;

    categories = [
        {
            id: 'hair',
            name: 'Hair Services',
            icon: '✂️',
            subCategories: [
                {
                    name: 'Hair Style',
                    items: ['Kids cuts', 'Trendy kids cut', 'U cut', 'Basic cut', 'Advance layer cuts']
                },
                {
                    name: 'Hair Coloring',
                    items: ['Global hair coloring', 'Streaking highlights', 'Root touch up']
                }
            ]
        },
        {
            id: 'nails',
            name: 'Nail Services',
            icon: '💅',
            subCategories: [
                {
                    name: 'Manicure',
                    items: ['Basic manicure', 'Gel manicure', 'French manicure', 'Nail extensions']
                }
            ]
        },
        {
            id: 'facial',
            name: 'Facial & Skin Care',
            icon: '✨',
            subCategories: [
                {
                    name: 'Facials',
                    items: ['Gold facial', 'Diamond facial', 'Chemical peel', 'Brightening facial']
                }
            ]
        },
        {
            id: 'bridal',
            name: 'Bridal Services',
            icon: '💎',
            subCategories: [
                {
                    name: 'Bridal Packages',
                    items: ['Complete bridal makeup', 'Bridal hair styling', 'Bridal package']
                }
            ]
        },
        {
            id: 'waxing',
            name: 'Waxing Services',
            icon: '🌹',
            subCategories: [
                {
                    name: 'Waxing',
                    items: ['Full body waxing', 'Face waxing', 'Eyebrow waxing']
                }
            ]
        },
        {
            id: 'mehandi',
            name: 'Mehandi Art',
            icon: '🎨',
            subCategories: [
                {
                    name: 'Mehandi Designs',
                    items: ['Bridal mehandi', 'Party mehandi', 'Traditional designs']
                }
            ]
        }
    ];

    constructor(private route: ActivatedRoute) {}

    ngOnInit(): void {
        this.route.queryParams.subscribe(params => {
            const category = params['category'];
            if (category) {
                this.activeCategory = category;
                setTimeout(() => this.scrollToCategory(category), 300);
            }
        });
    }

    @HostListener('window:scroll', ['$event'])
    onWindowScroll() {
        const offset = window.pageYOffset || document.documentElement.scrollTop || 0;
        this.isSticky = offset > 300;

        if (!this.isProgrammaticScroll) {
            this.updateActiveCategory();
        }
    }

    scrollToCategory(categoryId: string) {
        this.isProgrammaticScroll = true;
        const element = document.getElementById(categoryId);
        if (element) {
            const offset = 120;
            const elementPosition = element.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - offset;
            window.scrollTo({
                top: offsetPosition,
                behavior: 'smooth'
            });
            this.activeCategory = categoryId;

            setTimeout(() => {
                this.isProgrammaticScroll = false;
            }, 800);
        }
    }

    updateActiveCategory() {
        const sections = this.categories.map(cat => ({
            id: cat.id,
            element: document.getElementById(cat.id)
        }));

        for (const section of sections) {
            if (section.element) {
                const rect = section.element.getBoundingClientRect();
                if (rect.top >= 0 && rect.top <= 300) {
                    this.activeCategory = section.id;
                    break;
                }
            }
        }
    }
}
